"use client"

import { useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Moon, Star, CheckCircle, Trophy } from "lucide-react"

export interface UserData {
  n: string
  r: string
}

interface ThankYouPageProps {
  userData: UserData
  score: number
  totalQuestions: number
  answers: Record<number, number>
}

// Google Apps Script Web App URL
const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzn8kQh6EIfR1TVV7rF42awHFwMnx4tXxVTlKZ6nUjzhWqwr8hkPsMbNLFlE1FFSL_HVg/exec"

export default function ThankYouPage({
  userData,
  score,
  totalQuestions,
  answers,
}: ThankYouPageProps) {
  const percentage = Math.round((score / totalQuestions) * 100)

  // Send data to Google Sheets
  useEffect(() => {
    const sendToGoogleSheets = async () => {
      if (!GOOGLE_SCRIPT_URL) {
        console.log("Google Script URL not configured. Data:", {
          name: userData.n,
          roll: userData.r,
          answers: JSON.stringify(answers),
          score,
          totalQuestions,
          submittedAt: new Date().toISOString(),
        })
        return
      }

      try {
        await fetch(GOOGLE_SCRIPT_URL, {
          method: "POST",
          mode: "no-cors",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            name: userData.n,
            roll: userData.r,
            answers: JSON.stringify(answers),
            score,
            totalQuestions,
            submittedAt: new Date().toISOString(),
          }),
        })
        console.log("Data sent to Google Sheets successfully")
      } catch (error) {
        console.error("Error sending data to Google Sheets:", error)
      }
    }

    sendToGoogleSheets()
  }, [userData, score, totalQuestions, answers])

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4 relative overflow-hidden">
      {/* Decorative Elements */}
      <div className="absolute inset-0 opacity-5">
        <div className="absolute top-10 left-10 text-primary">
          <Moon className="w-24 h-24" />
        </div>
        <div className="absolute top-20 right-20 text-accent">
          <Star className="w-16 h-16" />
        </div>
        <div className="absolute bottom-20 left-1/4 text-primary">
          <Star className="w-12 h-12" />
        </div>
        <div className="absolute top-1/3 right-10 text-accent">
          <Moon className="w-20 h-20" />
        </div>
      </div>

      <Card className="max-w-lg w-full border-primary/20 shadow-xl relative z-10">
        <CardHeader className="text-center pb-2">
          <div className="flex justify-center mb-4">
            <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
              <CheckCircle className="w-12 h-12 text-primary" />
            </div>
          </div>
          <CardTitle className="text-2xl md:text-3xl text-foreground">
            জাযাকাল্লাহু খাইরান!
          </CardTitle>
          <p className="text-muted-foreground mt-2">
            আপনার কুইজ সফলভাবে জমা হয়েছে
          </p>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* User Info */}
          <div className="bg-secondary/50 rounded-lg p-4 space-y-2">
            <div className="flex justify-between">
              <span className="text-muted-foreground">নাম:</span>
              <span className="font-medium text-foreground">{userData.n}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">রোল:</span>
              <span className="font-medium text-foreground">{userData.r}</span>
            </div>
          </div>

          {/* Score Display */}
          <div className="text-center py-6">
            <div className="flex items-center justify-center gap-2 mb-2">
              <Trophy className="w-8 h-8 text-accent" />
            </div>
            <div className="text-5xl font-bold text-primary mb-2">
              {score}/{totalQuestions}
            </div>
            <div className="text-lg text-muted-foreground">
              আপনার স্কোর: {percentage}%
            </div>
          </div>

          {/* Score Bar */}
          <div className="w-full h-4 bg-secondary rounded-full overflow-hidden">
            <div
              className="h-full bg-primary transition-all duration-1000 ease-out"
              style={{ width: `${percentage}%` }}
            />
          </div>

          {/* Message */}
          <div className="text-center p-4 bg-accent/10 rounded-lg border border-accent/20">
            <p className="text-foreground">
              {percentage >= 80
                ? "অসাধারণ! আপনি চমৎকার করেছেন!"
                : percentage >= 60
                ? "বেশ ভালো! আরও চর্চা করুন।"
                : percentage >= 40
                ? "ভালো চেষ্টা! আরও পড়াশোনা করুন।"
                : "হাল ছাড়বেন না! আবার চেষ্টা করুন।"}
            </p>
          </div>

          {/* Footer Note */}
          <div className="text-center text-sm text-muted-foreground">
            <p>ফলাফল শীঘ্রই ঘোষণা করা হবে।</p>
            <p className="mt-1">রমাদান মোবারক!</p>
          </div>

          {/* Decorative */}
          <div className="flex justify-center gap-2 pt-4">
            <Moon className="w-6 h-6 text-primary" />
            <Star className="w-5 h-5 text-accent" />
            <Moon className="w-6 h-6 text-primary" />
          </div>
        </CardContent>
      </Card>
    </div>
  )
}
