"use client"

import { useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Label } from "@/components/ui/label"
import { Clock, User, Hash, AlertTriangle, Moon, Send, ChevronLeft, ChevronRight } from "lucide-react"
export interface Question {
  id: number
  q: string
  o: string[]
  a: number
}

export interface UserData {
  n: string
  r: string
}

interface QuizInterfaceProps {
  userData: UserData
  questions: Question[]
  answers: Record<number, number>
  timeRemaining: number
  onAnswerSelect: (questionId: number, optionIndex: number) => void
  onSubmit: () => void
  tabSwitchCount: number
  hAuto?: () => void
}

export default function QuizInterface({
  userData,
  questions,
  answers,
  timeRemaining,
  onAnswerSelect,
  onSubmit,
  tabSwitchCount,
}: QuizInterfaceProps) {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`
  }

  const answeredCount = Object.keys(answers).length
  const isLowTime = timeRemaining <= 300 // 5 minutes warning
  const currentQuestion = questions[currentQuestionIndex] || questions[0]
  const isAnswered = currentQuestion && answers[currentQuestion.id] !== undefined

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1)
    }
  }

  const handlePrevious = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1)
    }
  }

  const handleQuestionJump = (index: number) => {
    setCurrentQuestionIndex(index)
  }

  return (
    <div className="min-h-screen bg-background select-none">
      {/* Fixed Header */}
      <header className="fixed top-0 left-0 right-0 bg-card border-b border-border shadow-sm z-50">
        <div className="container mx-auto px-4 py-3">
          <div className="flex flex-wrap items-center justify-between gap-3">
            {/* User Info */}
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <User className="w-4 h-4 text-primary" />
                <span className="text-sm font-medium text-foreground">{userData.n}</span>
              </div>
              <div className="flex items-center gap-2">
                <Hash className="w-4 h-4 text-primary" />
                <span className="text-sm font-medium text-foreground">{userData.r}</span>
              </div>
            </div>

            {/* Timer */}
            <div
              className={`flex items-center gap-2 px-4 py-2 rounded-lg ${
                isLowTime ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary"
              }`}
            >
              <Clock className={`w-5 h-5 ${isLowTime ? "animate-pulse" : ""}`} />
              <span className="text-lg font-bold font-mono">{formatTime(timeRemaining)}</span>
            </div>

            {/* Tab Switch Warning */}
            {tabSwitchCount > 0 && (
              <div className="flex items-center gap-2 px-3 py-1 bg-destructive/10 text-destructive rounded-lg">
                <AlertTriangle className="w-4 h-4" />
                <span className="text-sm font-medium">
                  সতর্কতা: {tabSwitchCount}/2
                </span>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 pt-24 pb-32">
        <div className="max-w-4xl mx-auto space-y-6">
          {/* Progress */}
          <div className="flex items-center justify-between text-sm text-muted-foreground mb-4">
            <span>
              প্রশ্ন {currentQuestionIndex + 1} / {questions.length}
            </span>
            <span>
              উত্তর দেওয়া হয়েছে: {answeredCount}/{questions.length}
            </span>
          </div>

          {/* Progress Bar */}
          <div className="w-full h-2 bg-secondary rounded-full overflow-hidden">
            <div
              className="h-full bg-primary transition-all duration-300"
              style={{ width: `${(answeredCount / questions.length) * 100}%` }}
            />
          </div>

          {/* Current Question */}
          {currentQuestion && (
            <Card className="border-primary/20 shadow-md">
              <CardHeader className="pb-4">
                <CardTitle className="text-xl md:text-2xl text-foreground flex items-start gap-4">
                  <span className="flex items-center justify-center w-10 h-10 rounded-full bg-primary text-primary-foreground text-sm font-bold flex-shrink-0">
                    {currentQuestionIndex + 1}
                  </span>
                  <span className="leading-relaxed pt-1">{currentQuestion && currentQuestion.q}</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <RadioGroup
                  value={answers[currentQuestion.id] !== undefined ? answers[currentQuestion.id].toString() : ""}
                  onValueChange={(value) => {
                    if (answers[currentQuestion.id] === undefined) {
                      onAnswerSelect(currentQuestion.id, parseInt(value))
                    }
                  }}
                  className="space-y-3"
                >
                  {currentQuestion && currentQuestion.o && currentQuestion.o.map((option, optionIndex) => {
                    const isAnswered = answers[currentQuestion.id] !== undefined
                    const isSelected = answers[currentQuestion.id] === optionIndex
                    
                    return (
                      <div
                        key={optionIndex}
                        className={`flex items-center gap-3 p-4 rounded-lg border transition-all ${
                          isAnswered ? "cursor-not-allowed opacity-75" : "cursor-pointer hover:bg-secondary/50"
                        } ${
                          isSelected
                            ? "border-primary bg-primary/5"
                            : "border-border"
                        }`}
                        onClick={() => {
                          if (!isAnswered) {
                            onAnswerSelect(currentQuestion.id, optionIndex)
                          }
                        }}
                      >
                        <RadioGroupItem
                          value={optionIndex.toString()}
                          id={`q${currentQuestion.id}-o${optionIndex}`}
                          className="border-primary text-primary"
                          disabled={isAnswered}
                        />
                        <Label
                          htmlFor={`q${currentQuestion.id}-o${optionIndex}`}
                          className={`flex-1 ${isAnswered ? "cursor-not-allowed" : "cursor-pointer"} text-foreground`}
                        >
                          {option}
                        </Label>
                        {isAnswered && isSelected && (
                          <span className="text-xs text-muted-foreground font-medium">লক করা</span>
                        )}
                      </div>
                    )
                  })}
                </RadioGroup>
              </CardContent>
            </Card>
          )}

          {/* Question Navigation Grid */}
          <div className="bg-card p-4 rounded-lg border border-border">
            <p className="text-sm text-muted-foreground mb-3">দ্রুত নেভিগেশন:</p>
            <div className="grid grid-cols-5 sm:grid-cols-6 md:grid-cols-10 gap-2">
              {questions.map((q, index) => (
                <button
                  key={q.id}
                  onClick={() => handleQuestionJump(index)}
                  className={`w-full h-10 rounded-lg font-medium text-sm transition-all ${
                    currentQuestionIndex === index
                      ? "bg-primary text-primary-foreground"
                      : answers[q.id] !== undefined
                        ? "bg-primary/20 text-primary border border-primary/30 hover:bg-primary/30"
                        : "bg-secondary text-foreground border border-border hover:bg-muted"
                  }`}
                >
                  {index + 1}
                </button>
              ))}
            </div>
          </div>
        </div>
      </main>

      {/* Fixed Footer */}
      <footer className="fixed bottom-0 left-0 right-0 bg-card border-t border-border shadow-lg">
        <div className="container mx-auto px-4 py-4">
          <div className="max-w-4xl mx-auto flex items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-muted-foreground">
              <Moon className="w-5 h-5 text-primary" />
              <span className="text-sm">CPI Timeline Quiz 2026</span>
            </div>

            <div className="flex items-center gap-3">
              <Button
                onClick={handlePrevious}
                disabled={currentQuestionIndex === 0}
                variant="outline"
                className="px-4"
              >
                <ChevronLeft className="w-4 h-4 mr-1" />
                আগে
              </Button>

              <Button
                onClick={handleNext}
                disabled={currentQuestionIndex === questions.length - 1}
                className="bg-primary text-primary-foreground hover:bg-primary/90 px-4"
              >
                পরে
                <ChevronRight className="w-4 h-4 ml-1" />
              </Button>

              <Button
                onClick={onSubmit}
                className="bg-primary text-primary-foreground hover:bg-primary/90 px-6 md:px-8"
              >
                <Send className="w-4 h-4 mr-2" />
                সাবমিট
              </Button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  )
}
